programa
{
    funcao inteiro fatorial(inteiro n)
    {
        inteiro fato, i

        se (n < 0)
        {
            retorne 0
        }

        fato = 1
        i = 1
        para (i = 1; i <= n; i++)
        {
            escreva(i, "\n")
            fato = fato * i
        }
        retorne fato
    }

    funcao inicio()
    {
        inteiro n
        escreva("Digite n: ")
        leia(n)
        escreva("Fatorial: ", fatorial(n), "\n")
    }
}
